import pytest
from ta_attenuator.fading_scenario import SingleCellLinearFadingScenario, LinearFadingScenario


def test_wrapping_into_fading_scenario_is_transparent_for_FadingScenario_instances(empty_fading_scenario_class):
    from ta_attenuator.fading_scenario import wrap_into_fading_scenario

    fading_scenario_class_instance = empty_fading_scenario_class()

    assert wrap_into_fading_scenario(fading_scenario_class_instance) == fading_scenario_class_instance


def test_wrapping_into_fading_scenario_raises_IncorrectGeneratorType_for_noniterators():
    from ta_attenuator.fading_scenario import IncorrectGeneratorType
    from ta_attenuator.fading_scenario import wrap_into_fading_scenario

    def fading_scenario_as_function():
        return "50%"

    with pytest.raises(IncorrectGeneratorType):
        assert wrap_into_fading_scenario(fading_scenario_as_function)


@pytest.mark.parametrize("time_passed,expected_value",
                         [(0.3, 1),
                          (0.4, 1),
                          (0.5, 2),
                          (0.6, 2),
                          (0.7, 2),
                          (0.8, 2),
                          (0.9, 3)]
                         )
def test_attenuation_value_calculation_for_single_cell_linear_scenario(time_passed, expected_value):
    deattenuated_cell = "ENB_1_CELL_1"
    fading_step = "0.7db"
    fading_interval = "0.3s"
    fading_min = 1
    fading_max = 90
    scenario = SingleCellLinearFadingScenario(deattenuated_cell, fading_step, fading_interval, fading_min, fading_max)
    assert scenario._calculate_attenuation(time_passed) == expected_value


@pytest.mark.parametrize("time_passed,expected_value",
                         [(0.3, 1),
                          (0.4, 1),
                          (0.5, 2),
                          (0.6, 2),
                          (0.7, 2),
                          (0.8, 2),
                          (0.9, 3)]
                         )
def test_attenuation_value_calculation_for_linear_scenario(time_passed, expected_value):
    attenuated_cell = "ENB_1_CELL_1"
    deattenuated_cell = "ENB_2_CELL_1"
    fading_step = "0.7db"
    fading_interval = "0.3s"
    fading_min = 1
    fading_max = 90
    scenario = LinearFadingScenario(deattenuated_cell, attenuated_cell, fading_step, fading_interval, fading_min,
                                    fading_max)
    assert scenario._calculate_attenuation(time_passed) == expected_value


@pytest.fixture
def empty_fading_scenario_class():
    from ta_attenuator.fading_scenario import FadingScenario

    class EmptyFadingScenario(FadingScenario):
        def get_rf_paths(self):
            return []

        def get_attenuation_on_rf_path(self, rf_path_name):
            return 0.0

        def get_nearest_attenuation_timepoint(self):
            return 0.0

    return EmptyFadingScenario
